{
  "title": "The Journey of a Weave",
  "description": "Before a single thread touches the loom, a long, deliberate process unfolds. Cotton and silk yarns are carefully selected for strength and texture. Natural and modern dyes are prepared to achieve exact, enduring colour. The yarn is measured, stretched, and set in a process called warping, the invisible architecture behind every pattern. Then begins the weaving itself: hours, sometimes days, of rhythmic hand and foot movement, each pass of the shuttle building the fabric thread by thread.",
  "highlight": "What emerges is never mass-produced, never identical, never rushed.",
  "closing": "From Thread to Timeless.",
  "steps": [
    {
      "number": "01",
      "title": "Yarn Selection",
      "description": "Sourcing premium mulberry silk and high-grade organic cotton threads."
    },
    {
      "number": "02",
      "title": "Natural Dyeing",
      "description": "Immersing yarn in organic vegetable dyes for rich, breathable, long-lasting colors."
    },
    {
      "number": "03",
      "title": "Loom Warping",
      "description": "Setting up thousands of individual warp threads on traditional wooden frames manually."
    },
    {
      "number": "04",
      "title": "Weaving & Zari",
      "description": "Skillfully interlacing weft threads with optional pure silver and gold zari borders."
    }
  ]
}

